package hu.synostream.android;
import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Port of the Windows metadata-only preparation workflow, not legacy auto-start task creation. */
public final class DownloadStation {
    public static final String TASK="SYNO.DownloadStation.Task",TASK2="SYNO.DownloadStation2.Task",LIST="SYNO.DownloadStation2.Task.List",POLL="SYNO.DownloadStation2.Task.List.Polling",LOCATION="SYNO.DownloadStation2.Settings.Location";
    interface Persistence {String get(String key,String fallback);void put(String key,String value);default void durable(String key,String value){put(key,value);}}
    interface Transport {JSONObject call(String api,String method,boolean readonly,JSONObject params,String name,byte[] file)throws Exception;}
    private final java.util.function.LongSupplier clock;private static final long SUBMITTED_TTL=24*60*60*1000L;private Transport transport;private final NasClient nas;private final Persistence store;private final String owner;private boolean connected;
    final Map<String,JSONObject> prepared=new LinkedHashMap<>();
    public DownloadStation(NasClient source,Persistence storage,String identity){this(source,storage,identity,null);}
    DownloadStation(Transport transport,Persistence storage,String identity){this(null,storage,identity,transport);}
    DownloadStation(Transport transport,Persistence storage,String identity,java.util.function.LongSupplier clock){this(null,storage,identity,transport,clock);}
    private DownloadStation(NasClient source,Persistence storage,String identity,Transport transport){this(source,storage,identity,transport,System::currentTimeMillis);}
    private DownloadStation(NasClient source,Persistence storage,String identity,Transport transport,java.util.function.LongSupplier clock){this.clock=clock;nas=source;connected=source!=null;store=storage;owner=identity;this.transport=transport;try{JSONArray lists=new JSONArray(store.get("prepared:"+owner,"[]"));for(int i=0;i<lists.length();i++){JSONObject item=lists.getJSONObject(i);prepared.put(item.getString("list_id"),item);}}catch(Exception ignored){}pruneSubmitted();}
    public synchronized void pruneSubmitted(){long now=clock.getAsLong();boolean changed=false;Iterator<JSONObject> iterator=prepared.values().iterator();while(iterator.hasNext()){JSONObject item=iterator.next();if(!item.optBoolean("submitted"))continue;long at=item.optLong("submitted_at",-1);if(at<0){try{item.put("submitted_at",now);}catch(JSONException invalid){throw new IllegalStateException(invalid);}changed=true;}else if(now>=at&&now-at>SUBMITTED_TTL){store.put("torrent_choice:"+owner+":"+item.optString("list_id"),"");iterator.remove();changed=true;}}if(changed)persist();}
    public synchronized List<JSONObject> snapshotPrepared(){List<JSONObject> snapshot=new ArrayList<>();try{for(JSONObject item:prepared.values())snapshot.add(new JSONObject(item.toString()));}catch(JSONException invalid){throw new IllegalStateException(invalid);}return snapshot;}
    private void persist(){store.durable("prepared:"+owner,new JSONArray(prepared.values()).toString());}
    public synchronized void close(){connected=false;}
    private synchronized JSONObject request(String api,String method,boolean readonly,JSONObject params,String name,byte[] file)throws Exception{if(transport!=null)return transport.call(api,method,readonly,params,name,file);if(!connected)throw new IOException("A Download Station-kapcsolat lezárult. Nyisd meg újra a Letöltéseket.");Map<String,String> values=new LinkedHashMap<>();for(Iterator<String> it=params.keys();it.hasNext();){String key=it.next();Object value=params.get(key);values.put(key,api.startsWith("SYNO.DownloadStation2")?jsonValue(value):String.valueOf(value));}return nas.apiRequest(api,method,api.equals(LOCATION)?1:api.equals(TASK)?1:2,readonly,values,name,file,"torrent");}
    private static String jsonValue(Object value){String array=new JSONArray().put(value).toString();return array.substring(1,array.length()-1);}
    private JSONObject request(String api,String method,boolean readonly,JSONObject params)throws Exception{return request(api,method,readonly,params,null,null);}
    public static String destination(String value){String clean=value.trim().replace('\\','/');if(clean.startsWith("syno://"))clean=clean.substring(7);List<String> parts=new ArrayList<>();for(String part:clean.split("/")){if(part.equals(".")||part.equals("..")||part.indexOf(0)>=0)throw new IllegalArgumentException("A célmappa nem tartalmazhat relatív útvonalat.");if(!part.isEmpty())parts.add(part);}return String.join("/",parts);}
    public static String uri(String value){value=value.trim();if(value.contains("\r")||value.contains("\n")||value.indexOf(0)>=0)throw new IllegalArgumentException("Egyszerre egy hivatkozást adj meg.");URI uri=URI.create(value);String scheme=uri.getScheme()==null?"":uri.getScheme().toLowerCase(Locale.ROOT);if(scheme.equals("magnet")){boolean found=false;for(String item:Objects.toString(uri.getRawQuery(),Objects.toString(uri.getRawSchemeSpecificPart(),"").replaceFirst("^\\?","")).split("&")){String[] pair=item.split("=",2);if(pair.length==2&&pair[0].equals("xt")&&URLDecoder.decode(pair[1],java.nio.charset.StandardCharsets.UTF_8).toLowerCase(Locale.ROOT).startsWith("urn:btih:"))found=true;}if(!found)throw new IllegalArgumentException("Hiányos magnetlink.");}else if(!Set.of("http","https").contains(scheme)||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException("Magnet-, HTTP- vagy HTTPS-hivatkozást adj meg.");return value;}
    public static boolean defaultSelected(String name){return defaultSelected(name,"");}
    public static boolean defaultSelected(String name,String root){return !MediaLogic.samplePath(name,root,false,false);}
    public static JSONArray files(JSONObject metadata)throws Exception{JSONArray files=metadata.optJSONArray("files");if(files==null||files.length()==0||files.length()>50000)throw new IOException("A NAS még nem adott fájllistát. A letöltés nem indult el.");Set<Integer> seen=new HashSet<>();for(int i=0;i<files.length();i++){JSONObject item=files.getJSONObject(i);Object index=item.opt("index");if(!(index instanceof Integer)||((Integer)index)<0||!seen.add((Integer)index)||item.optString("name").isBlank())throw new IOException("Hiányos vagy ismétlődő fájllista. A letöltés nem indult el.");}return files;}
    public synchronized List<JSONObject> tasks()throws Exception{
        List<JSONObject> all=new ArrayList<>();Set<String> seen=new HashSet<>();int offset=0,reported=0;
        // Some DSM responses count only the returned page. Never treat a full page
        // (or a capped page) as the end: confirm exhaustion with an empty page.
        while(offset<=10000){
            if(Thread.currentThread().isInterrupted())throw new InterruptedException();
            JSONObject result=request(TASK,"list",true,new JSONObject().put("offset",offset).put("limit",100).put("additional","detail,transfer"));
            JSONArray batch=result.optJSONArray("tasks");if(batch==null)throw new IOException("Hiányos Download Station-feladatlista.");reported=Math.max(reported,result.optInt("total",0));
            if(batch.length()==0){if(all.size()<reported)throw new IOException("Hiányos feladatlista. A korábbi lista megmaradt.");return all;}
            for(int i=0;i<batch.length();i++){JSONObject task=batch.getJSONObject(i);String id=task.optString("id");if(id.isEmpty()||!seen.add(id))throw new IOException("Ismétlődő feladatlista. A korábbi lista megmaradt.");if(all.size()>=10000)throw new IOException("Túl sok letöltési feladat.");all.add(task);}
            offset+=batch.length();
        }throw new IOException("Túl sok letöltési feladat.");
    }
    public synchronized void action(String action,Set<String> ids)throws Exception{if(!Set.of("resume","pause","delete").contains(action)||ids.isEmpty()||ids.stream().anyMatch(id->id.isBlank()||id.contains(",")))throw new IllegalArgumentException("Válassz érvényes feladatot.");JSONObject params=new JSONObject().put("id",String.join(",",ids));if(action.equals("delete"))params.put("force_complete","false");request(TASK,action,false,params);}
    public synchronized List<JSONObject> prepare(String link,String filename,byte[] bytes,String folder)throws Exception{if((bytes!=null)==!link.isBlank())throw new IllegalArgumentException("Egy hivatkozást vagy egy torrentfájlt válassz.");String target=destination(folder);if(target.isEmpty())target=destination(request(LOCATION,"get",true,new JSONObject()).optString("default_destination"));if(target.isEmpty())throw new IOException("Válassz célmappát a NAS-on. A letöltés nem indult el.");JSONObject params=new JSONObject().put("type",bytes==null?"url":"file").put("destination",target).put("create_list",true);if(bytes==null)params.put("url",new JSONArray().put(uri(link)));else{if(filename==null||!filename.toLowerCase(Locale.ROOT).endsWith(".torrent")||bytes.length==0||bytes.length>32*1024*1024)throw new IllegalArgumentException("Legfeljebb 32 MiB méretű .torrent fájlt válassz.");params.put("file",new JSONArray().put("torrent")).put("size",bytes.length);}JSONObject result=request(TASK2,"create",false,params,filename,bytes);Object returned=result.opt("list_id");JSONArray ids=returned instanceof JSONArray?(JSONArray)returned:returned instanceof String?new JSONArray().put(returned):null;if(ids==null||ids.length()==0)throw new IOException("A NAS nem igazolta a fájllista előkészítését. Letöltés nem indult.");List<JSONObject> results=new ArrayList<>();for(int i=0;i<ids.length();i++){String id=ids.optString(i);if(id.isBlank())throw new IOException("Érvénytelen fájllista-azonosító.");JSONObject placeholder=new JSONObject().put("list_id",id).put("destination",target).put("submitted",false);prepared.put(id,placeholder);persist();try{JSONObject metadata=request(LIST,"get",true,new JSONObject().put("list_id",id));JSONArray files=files(metadata);JSONObject preview=new JSONObject(placeholder.toString()).put("files",files).put("title",metadata.optString("title","Torrent"));prepared.put(id,preview);results.add(preview);persist();}catch(Exception e){try{discard(id);}catch(Exception ignored){}throw e;}}return results;}
    public synchronized void discard(String id)throws Exception{JSONObject item=prepared.get(id);if(item==null||item.optBoolean("submitted"))return;request(LIST,"delete",false,new JSONObject().put("list_id",id));prepared.remove(id);persist();}
    public synchronized void start(String id,Set<Integer> selected)throws Exception{JSONObject item=prepared.get(id);if(item==null||item.optBoolean("submitted"))throw new IOException("Ez a fájllista már elküldött vagy lejárt. Ellenőrizd a feladatlistát.");JSONArray files=files(item);Set<Integer> valid=new HashSet<>();for(int i=0;i<files.length();i++)valid.add(files.getJSONObject(i).getInt("index"));if(selected.isEmpty()||!valid.containsAll(selected))throw new IllegalArgumentException("Legalább egy érvényes fájlt jelölj ki.");item.put("submitted",true).put("submitted_at",clock.getAsLong());persist();JSONObject started;try{started=request(POLL,"download",false,new JSONObject().put("list_id",id).put("selected",new JSONArray(new TreeSet<>(selected))).put("destination",item.getString("destination")).put("create_subfolder",true));}catch(NasClient.ApiRejectedException rejected){item.put("submitted",false);persist();throw rejected;}String ticket=started.optString("task_id");if(ticket.isBlank())throw new IOException("Nincs biztos indítási visszaigazolás. Ellenőrizd a feladatlistát; ne add hozzá ismét automatikusan.");long end=System.nanoTime()+90_000_000_000L;while(System.nanoTime()<end){JSONObject state=request(POLL,"download_status",true,new JSONObject().put("task_id",ticket));if(state.optBoolean("finish")){try{request(POLL,"download_stop",false,new JSONObject().put("task_id",ticket));}catch(Exception ignored){}if(!state.optBoolean("success")){item.put("submitted",false);persist();throw new IOException("A NAS nem tudta elindítani a kijelölt fájlokat. A fájlválasztás újrapróbálható.");}prepared.remove(id);persist();return;}Thread.sleep(500);}throw new IOException("Az indítás visszaigazolása lejárt. Ellenőrizd a feladatlistát; automatikus ismétlés nem történt.");}
}
